#if canImport(SwiftUI)
import SwiftUI
import KnowledgeOSCoreBridge
@MainActor final class DocumentReaderViewModel:ObservableObject { @Published private(set) var descriptor:DocumentDescriptorDTO?; @Published private(set) var page:DocumentPageDTO?; @Published private(set) var isLoading=false; @Published var errorMessage:String?; @Published var zoom:Double=1; private let service:DocumentService; init(service:DocumentService){self.service=service}; var canGoBackward:Bool{(page?.pageNumber ?? 1)>1}; var canGoForward:Bool{guard let p=page else{return false}; return p.pageNumber<p.pageCount}; var progress:Double{guard let p=page else{return 0}; return Double(p.pageNumber)/Double(max(1,p.pageCount))}; func open(id:String) async {isLoading=true; defer{isLoading=false}; do{let d=try await service.open(id:id); descriptor=d; let saved=try await service.location(id:id); await loadPage(saved?.pageNumber ?? 1,save:false)}catch{errorMessage=error.localizedDescription}}; func nextPage() async{guard let p=page,p.pageNumber<p.pageCount else{return}; await loadPage(p.pageNumber+1)}; func previousPage() async{guard let p=page,p.pageNumber>1 else{return}; await loadPage(p.pageNumber-1)}; func goToSection(_ s:DocumentSectionDTO) async{await loadPage(s.pageNumber)}; private func loadPage(_ n:Int,save:Bool=true) async{guard let d=descriptor else{return}; do{page=try await service.page(id:d.id,pageNumber:n); if save{_ = try await service.saveLocation(id:d.id,pageNumber:n,progress:Double(n)/Double(max(1,d.pageCount)))}}catch{errorMessage=error.localizedDescription}} }
#endif
